mapper.select:
SELECT *
FROM (SELECT a.*, rownum rnum
      FROM (SELECT
                no,
                category,
                views,
                title,
                id,
                create_date AS createDate,
                update_date AS updateDate
            FROM QUESTION
            WHERE id = #{id}
            AND category IN (20, 30)

            ORDER BY no DESC
           ) a WHERE rownum <= #{pagination.start} + #{pagination.size}
     ) WHERE rnum > #{pagination.start}

mapper.update:
UPDATE QUESTION
SET views = views + 1
WHERE no = #{no}

UPDATE QUESTION
SET category = #{newCategory},
    update_date = CURRENT_TIMESTAMP
WHERE no = #{no}
  AND category = #{expectedCategory}
